window.Folio=(()=>{
 const names=['鉄笠のボル','白衛のセラ','藍剣のレイン','煉瓦門のガド','灰杖のマルタ','星読みのイオ','露草のニム','燈火のサヤ','伏葉のロク','夜渡りのユラ','黄衣のハル','赤弦のラウ','巡礼のエノ','白頁のノア','石庭のドム','薔薇歌のリエ'];
 names.push('銀編みのニア','銅兜のオルム','潮剣のフィア','門守のバラク','塩読みのエマ','天測のリド','窯火のテナ','雨待ちのルネ','雪追いのユイ','弩番のグレン','果樹守のメイ','夕径のトワ','灯守のリネ','笑僧のバン','封書のエダ','灰祷のスイ');
 const second=new Image();second.src='data:image/png;base64,';
 const atlas=new Image();atlas.src='data:image/png;base64,';
 names.push(...["リゼ", "バルト", "イリア", "ドラン", "オルネ", "ザイン", "ヘルム", "ティア", "ゴラン", "リュト", "アンネ", "バルガ", "フィノ", "ウルク", "トニオ", "エリン", "ダイン", "ネリス", "ザガン", "テオ", "ライル", "ボルグ", "ルシア", "ガレン", "コル", "ユノ", "ヴェラ", "エイス", "ハサン", "ミナ", "セイル", "ナジム", "フレア", "ルミナ", "オド", "アステ", "リオン", "セレス", "ミゲル", "ニコ", "ソル", "ファロ", "リタ", "シオン", "ルクス", "ネオン", "エルダ", "ノイル", "ディノ", "アミ", "ユエ", "オルド", "マナ", "リリカ", "ペトラ", "アセル", "ロアン", "イリス", "ゴルド", "メル", "ルオ", "ダグ", "ラナ", "フェル", "シド", "タル", "アゼル", "マオ", "エルク", "ニル", "シルカ", "ベルン", "キリ", "ダレス", "ロイ", "オルガ", "レム", "サナ", "コウ", "ラグ", "ヴィオ", "ブラム", "キア", "ナル", "コレット", "リーア", "ガイ", "ノエル", "メイサ", "エルモ", "リネル", "ガロ", "セシル", "ラウル", "ベルナ", "サリヤ", "ドイル", "フィル", "バゼル", "ミレア"]);
 const third=new Image();third.src='data:image/png;base64,';
 function key(p,volume=1){if(volume===3)return p.role*25+(p.appearanceSeed>>>0)%25;return p.role*4+(p.appearanceSeed>>>0)%4}
 function apply(p,volume=1){p.folioId=key(p,volume)+(volume===3?32:volume===2?16:0);p.name=names[p.folioId]}
 function draw(c,i){c.width=40;c.height=48;if(i>=32){if(third.naturalWidth)c.getContext("2d").drawImage(third,(i-32)%10*40,Math.floor((i-32)/10)*48,40,48,0,0,40,48);return}const sheet=i>=16?second:atlas;if(!sheet.naturalWidth)return;c.getContext('2d').drawImage(sheet,(i%4)*40,Math.floor(i%16/4)*48,40,48,0,0,40,48)}
 return {names,key,apply,draw,ready:fn=>Promise.all([atlas.decode(),second.decode(),third.decode()]).then(fn)};
})();